/// <summary>
/// returns the ProjTable record for the BatchProjId
/// </summary>
/// <param name = "_forUpdate">boolean</param>
/// <returns>ProjTable</returns>
public ProjTable avaBatchProjTable(boolean _forUpdate = false)
{
    return ProjTable::find(this.AVABatchProjId,_forUpdate);
}

/// <summary>
///    AVA <c>checkAVAPTMIsConversionTool</c> method.
/// </summary>
/// <param name="_dropEstimated">
///     <c>boolean</c> as type
/// </param>
/// <param name="_childBuffer">
///     <c>Common</c> as type
/// </param>
/// <param name="_expandBOMRoute">
///     <c>boolean</c> as type
/// </param>
public void insert( boolean _dropEstimated, 
                    Common  _childBuffer, 
                    boolean _expandBOMRoute )
{
    next insert(_dropEstimated, 
                _childBuffer,
                _expandBOMRoute );

    if(this.RecId)
    {
        ProdTable::checkAVAPTMIsConversionTool(this.ProdId, true);
    }
}

/// <summary>
///    AVA <c>checkAVAPTMIsConversionTool</c> method.
/// </summary>
/// <param name="_prodId">
///     <c>ProdId</c> as type
/// </param>
/// <param name="_update">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>AVAPTMisConversionTool</c> as return value
/// </returns>
public static AVAPTMisConversionTool checkAVAPTMIsConversionTool(ProdId _prodId, boolean _update = false)
{
    AVAPTMisConversionTool  retVal;

    ProdTable               locProdTable;

    KCS_PTMProdRouteTool    locKCS_PTMProdRouteTool;
    KCS_PTMToolTable        locKCS_PTMToolTable;

    select firstonly locKCS_PTMProdRouteTool
    where   locKCS_PTMProdRouteTool.ProdId == _prodId
        join    locKCS_PTMToolTable
        where   locKCS_PTMToolTable.ToolId                  == locKCS_PTMProdRouteTool.ToolId
            &&  locKCS_PTMToolTable.AVAPTMisConversionTool  == NoYes::Yes;

    retVal = locKCS_PTMToolTable.AVAPTMisConversionTool;

    if(_update)
    {
        locProdTable = ProdTable::find(_prodId);

        if(locProdTable.AVAPTMisConversionTool != locKCS_PTMToolTable.AVAPTMisConversionTool)
        {
            locProdTable.selectForUpdate(true);
            locProdTable.AVAPTMisConversionTool = locKCS_PTMToolTable.AVAPTMisConversionTool;
            locProdTable.update();
        }
    }
    return retVal;
}

/// <summary>
///     AVA <c>initReleasedProductSpecificDefaulting</c> method.
/// </summary>
/// <param name="_inventTable">
///     <c>InventTable</c> as type
/// </param>
public void initReleasedProductSpecificDefaulting(InventTable _inventTable)
{
    ProdPool    locProdPool;

    next initReleasedProductSpecificDefaulting(_inventTable);

    if(this.ProdPoolId)
    {
        locProdPool = ProdPool::find(this.ProdPoolId);
        this.NDX_ProductionScheduler    = locProdPool.NDX_ProductionScheduler;
        this.NDX_MasterInCharge         = locProdPool.NDX_MasterInCharge;
    }
}

/// <summary>
/// Extension of method initFromCaller
/// </summary>
/// <param name = "_callerBuffer">Common</param>
public void initFromCaller(Common _callerBuffer)
{
    ProjTable   projTable;

    next initFromCaller(_callerBuffer);

    switch (_callerBuffer.TableId)
    {
        case (tableNum(ProjTable))     :
            projTable = _callerBuffer as ProjTable;
            this.AVABatchProjId = projTable.ProjId;
            break;
    }
}

/// <summary>
/// Initializes the record based on a BOM version.
/// </summary>
/// <param name="_bomVersion">
/// The BOM version record from which to initialize.
/// </param>
/// <param name="_useBomVersionQty">
/// A Boolean value that indicates whether the quantity of the production should be updated based on
/// the batch size of the BOM version.
/// </param>
