{
    next initFromBOMVersion(_bomVersion, _useBomVersionQty);

    this.KCS_PTMProdTypeId = _bomVersion.AVAPTMProdTypeId;
}

/// <summary>
///     AVA <c>initFromSplitProdTable</c> method.
/// </summary>
/// <param name="_prodTable">
///     <c>ProdTable</c> as type
/// </param>
public void initFromSplitProdTable(ProdTable _prodTable) // old production
{
    next initFromSplitProdTable(_prodTable);

    this.AVAPTMisConversionTool     = _prodTable.AVAPTMisConversionTool;
    this.NDX_ProductionScheduler    = _prodTable.NDX_ProductionScheduler;
