}

/// <summary>
/// Counts the BOMVersion records that are linked to ProdTable.ItemId, Approved and within the from/to date
/// </summary>
/// <returns>True if more than one record found</returns>
public boolean avaHasSeveralBOM()
{
    BOMVersion avaBOMVersion;

    select count(RecId) from avaBOMVersion
        where avaBOMVersion.ItemId == this.ItemId
        && avaBOMVersion.Approved == NoYes::Yes
        && avaBOMVersion.FromDate >= dateNull()
        && avaBOMVersion.FromDate <= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
        && (avaBOMVersion.ToDate == dateNull()
            || (avaBOMVersion.ToDate >= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
            && avaBOMVersion.ToDate <= dateMax()));

    if(avaBOMVersion.RecId > 1)
    {
        return true;
    }

    return false;
}

/// <summary>
/// Counts the RouteVersion records that are linked to ProdTable.ItemId, Approved and within the from/to date
/// </summary>
/// <returns>True if more than one record found</returns>
public boolean avaHasSeveralRoute()
{
    RouteVersion avaRouteVersion;

    select count(RecId) from avaRouteVersion
        where avaRouteVersion.ItemId == this.ItemId
        && avaRouteVersion.Approved == NoYes::Yes
        && avaRouteVersion.FromDate >= dateNull()
        && avaRouteVersion.FromDate <= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
        && (avaRouteVersion.ToDate == dateNull()
            || (avaRouteVersion.ToDate >= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
            && avaRouteVersion.ToDate <= dateMax()));

    if(avaRouteVersion.RecId > 1)
    {
        return true;
    }

    return false;
}

/// <summary>
/// AVA
/// </summary>
/// <returns>ProdPoolId</returns>
public ProdPoolId avaProdPoolFromFirstOpr()
{
    ProdRoute                       prodRoute;
    WrkCtrTable                     wrkCtrTable;
    WrkCtrResourceGroup             wrkCtrGroup;
    RecId                           recId;
    WrkCtrId                        wrkCtrId;
    WrkCtrActivityRequirement       wrkCtrActivityRequirement;
    WrkCtrActivityRequirementType   relationShipType;
    ProdPoolId                      prodPoolId;

    select firstOnly prodRoute order by OprNum where prodRoute.ProdId == this.ProdId
                                              && prodRoute.OprPriority == RouteOprPriority::Primary;
    recId = prodRoute.activityRequirementSet().RecId;
    if (recId != 0)
    {
        select firstonly WrkCtrActivityRequirement
        where WrkCtrActivityRequirement.ActivityRequirementSet == recid;
        if (wrkCtrActivityRequirement)
        {
            wrkCtrId =  WrkCtrActivityRequirement.requirementEdit();
            relationShipType = wrkCtrActivityRequirement.RelationshipType;
            if (relationShipType == WrkCtrActivityRequirementType::ResourceGroup)
            {
                select firstonly wrkCtrGroup where wrkCtrGroup.WrkCtrId == wrkCtrId;
                prodPoolId = wrkCtrGroup.AVAProdPoolId;
            }
            else
            {
                select firstOnly wrkCtrTable where wrkCtrTable.WrkCtrId == WrkCtrId;
                prodPoolId = wrkCtrTable.AVAProdPoolId;
            }
        }
    }
    return prodPoolId;
}

/// <summary>
/// AVA
/// </summary>
public void avaSetProdPoolFromRoute()
{
    ProdPool        prodPool;
    ProdPoolId      poolId = this.avaProdPoolFromFirstOpr();

    if (poolId)
    {
        ttsbegin;
        this.selectForUpdate(true);
        this.ProdPoolId                 = poolId;
        prodPool                        = ProdPool::find(poolId);
        this.NDX_MasterInCharge         = prodPool.NDX_MasterInCharge;
        this.NDX_ProductionScheduler    = prodPool.NDX_ProductionScheduler;
        this.doUpdate();
        ttscommit;
    }
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_wrkCtrId">WrkCtrId</param>
public void avaSetProdPoolFromWrkCtrId(WrkCtrId _wrkCtrId)
{
    ProdPoolId                      prodPoolId;
    ProdPool                        prodPool;
    WrkCtrTable                     wrkCtrTable;
    WrkCtrResourceGroup             wrkCtrGroup;

    select firstonly AVAProdPoolId from wrkCtrGroup where wrkCtrGroup.WrkCtrId == _wrkCtrId;
    prodPoolId = wrkCtrGroup.AVAProdPoolId;
    if (!prodPoolId)
    {
        select firstOnly AVAProdPoolId from wrkCtrTable where wrkCtrTable.WrkCtrId == _WrkCtrId;
        prodPoolId = wrkCtrTable.AVAProdPoolId;
    }

    if (prodPoolId)
    {
        ttsbegin;
        this.selectForUpdate(true);
        this.ProdPoolId                 = prodPoolId;
        prodPool                        = ProdPool::find(prodPoolId);
        this.NDX_MasterInCharge         = prodPool.NDX_MasterInCharge;
        this.NDX_ProductionScheduler    = prodPool.NDX_ProductionScheduler;
        this.doUpdate();
        ttscommit;
    }
}

/// <summary>
/// AVA from AX2009 TASK NDX_TASK1235004488
/// </summary>
/// <param name = "fds">FormDataSource</param>
/// <returns>boolean</returns>
public static boolean NDX_StatusDecreaseAllowed(FormDataSource fds)
{
    MultiSelectionHelper msh;
    ProdTable lprodTable;
    int anz = 0;
    MenuFunction    locMenuFunction;

    if (fds.anyMarked())
    {
        msh = MultiSelectionHelper::construct();
        msh.parmDatasource(fds);
        lprodTable = msh.getFirst();
        while (lprodTable)
        {
            ++anz;
            lprodTable = msh.getNext();
        }
        if (anz > 1)
        {
            //if (!hasSecuritykeyAccess(securitykeynum(NDX_PAMultiStatusDecrease), AccessType::Edit))
            locMenuFunction = new MenuFunction(menuItemActionStr(AVAStatusDecreaseSecurity), MenuItemType::Action);
            if (!hasMenuItemSecurityAccess(locMenuFunction))
            {
                Error(strfmt("@NDX:NXADecreaseStatusSecurity",anz));     // Ihnen fehlt die Berechtigung, den PA-Status für mehrere PA's (%1) zurückzusetzen!
                return false;
            }


            // Sie haben insgesamt [%1] PA's für eine Status-Rücksetzung markiert. Soll der Vorgang fortgesetzt werden?
            if (box::yesNo(strfmt("@NDX:NXADecreaseStatusMultiple", anz), DialogButton::No) == DialogButton::No)
            {
                return false;
            }
        }
    }

    return true;
}

[
    SysClientCacheDataMethodAttribute(true)
]
display public static AVAProdTableHasBlockedWork avaDisplayHasBlockedWork(ProdTable _prodTable)
{
    AVAProdTableHasBlockedWork  prodTableHasBlockedWork;
    ProdBOM                     prodBOM;
    WHSWorkLine                 workLine;
    WHSWorkTable                workTable;

    select firstonly RecId from prodBOM
        where prodBOM.ProdId == _prodTable.ProdId
        exists join RecId from workLine
            where workLine.InventTransId == prodBOM.InventTransId
                join RecId from workTable
                    where workTable.WorkId == workLine.WorkId
                       && workTable.Frozen == NoYes::Yes
                       && workTable.WorkStatus != WHSWorkStatus::Cancelled
                       && workTable.WorkStatus != WHSWorkStatus::Closed;

    if (prodBOM)
    {
        prodTableHasBlockedWork = NoYes::Yes;
    }

    return prodTableHasBlockedWork;
}

/// <summary>
/// AVA/WEN/2024/12/18         AVA_012921_ProdRunMap
/// </summary>
