/// <summary>
/// AVA/WEN/2025/03/14  AVA_013157_ProdCalcDifference
/// </summary>
public void AVASetCostCalcDiff()
{
    ProdCalcTrans   prodCalcTrans,prodCalcTransMinLevel;
    real            costPriceSum;
    real            costAmountTotal;
    real            consSum;
    real            finishedGood;
    real            qtyCalcDiff;
    real            costCalcDiff;
    real            costCalcDiffTotal;
    real            costPricePcsDiff;
    real CostPricePcsCalc,CostPricePcsReal;
    ProdTable       prodTableUpd;

    select minof(CollectRefLevel) from prodCalcTransMinLevel
    index hint ProdCollectIdx
    where prodCalcTransMinLevel.TransRefId == this.ProdId
       && prodCalcTransMinLevel.CollectRefProdId == this.CollectRefProdId
       && prodCalcTransMinLevel.Resource == this.ItemId;

    select firstonly prodCalcTrans
    index hint ProdCollectIdx
    where prodCalcTrans.TransRefId == this.ProdId
       && prodCalcTrans.CollectRefProdId == this.CollectRefProdId
       && prodCalcTrans.CollectRefLevel == prodCalcTransMinLevel.CollectRefLevel
       && prodCalcTrans.Resource == this.ItemId;

    if (prodcalcTrans)
    {
        costPriceSum                    = prodCalcTrans.CostAmount + prodCalcTrans.CostMarkup;
        costAmountTotal                 = prodCalcTrans.RealCostAmount + prodCalcTrans.RealCostAdjustment;
        consSum                         = prodCalcTrans.consumptionSum();
        finishedGood                    = this.reportedFinishedGood();

        if (costPriceSum)
        {
            costCalcDiff = (costPriceSum - costAmountTotal) / costPriceSum * 100;
        }
        else
        {
            costCalcDiff = 0;
        }

        if (consSum)
        {
            qtyCalcDiff = (consSum - finishedGood) / consSum * 100;
        }
        else
        {
            qtyCalcDiff = 0;
        }

        if (qtyCalcDiff)
        {
            costCalcDiffTotal = (costCalcDiff - qtyCalcDiff) / qtyCalcDiff * 100;
        }
        else
        {
            costCalcDiffTotal = 0;
        }
        ttsbegin;
        prodTableUpd = ProdTable::find(this.ProdId, true);

        prodTableUpd.AVARealCostAmountTotal    = costAmountTotal;
        prodTableUpd.AVACostPriceSum           = costPriceSum;
        prodTableUpd.AVACostCalcDifference     = costCalcDiff * (-1);

        if (prodTableUpd.AVACostPricePcsCalc())
        {
            CostPricePcsCalc = prodTableUpd.AVACostPricePcsCalc();
            CostPricePcsReal = prodTableUpd.AVACostPricePcsReal();

            costPricePcsDiff = (prodTableUpd.AVACostPricePcsCalc() - prodTableUpd.AVACostPricePcsReal()) / prodTableUpd.AVACostPricePcsCalc() * 100;
        }
        else
        {
            costPricePcsDiff = 0;
        }

        prodTableUpd.AVACostPricePcsCalc = CostPricePcsCalc;
        prodTableUpd.AVACostPricePcsReal = CostPricePcsReal;

        prodTableUpd.AVACostPricePcsDiff       = costPricePcsDiff * (-1);
        prodTableUpd.doUpdate();
        ttscommit;
    }

}

/// <summary>
/// AVA/WEN/2025/03/14  AVA_013157_ProdCalcDifference
/// </summary>
/// <returns>CostProcePcs</returns>
display CostPricePcs AVACostPricePcsCalc()
{
    PriceUnit  priceUnit;

    priceUnit =  InventTable::find(this.ItemId).inventTableModuleInvent().priceUnit();
    return this.QtyCalc != 0 ? this.AVACostPriceSum / this.QtyCalc * priceUnit : 0;
}

/// <summary>
/// AVA/WEN/2025/03/14  AVA_013157_ProdCalcDifference
/// </summary>
/// <returns>CostPricePcs</returns>
display CostPricePcs AVACostPricePcsReal()
{
    PriceUnit  priceUnit;

    priceUnit =  InventTable::find(this.ItemId).inventTableModuleInvent().priceUnit();
    return this.reportedFinishedGood() ? this.AVARealCostAmountTotal / this.reportedFinishedGood()* priceUnit : 0;
}
